import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZRound38WaterSeedOracle extends GhidraScript{static final long RET=0x12345000L,S=0x7fff0000L,P=0x1800000L;long hash(byte[]b){long h=2166136261L;for(byte v:b)h=((h^(v&255))*16777619L)&0xffffffffL;return h;}long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(i*8);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<512;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{byte[]b=new byte[44];for(int i=0;i<44;i++)b[i]=(byte)(s*17+i*29);e.writeMemory(toAddr(P),b);for(long pc:new long[]{RET,0x460910})e.setBreakpoint(toAddr(pc));e.writeRegister("ESP",S);put(e,S,4,RET);put(e,S+4,4,P);int draws=0;if(!e.run(toAddr(s<256?0x403100:0x402d50),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=RET){long sp=e.readRegister("ESP").longValue();e.writeRegister("EAX",(s*2027)^(draws*7919)^0x7731a5c9);draws++;long ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}out.println(s+","+draws+","+hash(e.readMemory(toAddr(P),44)));}finally{e.dispose();}}}}}